def build(presentation_only=False):
    import platform
    import subprocess
    import scipy
    import numpy
    report_dir = OUT / "prose_revision_20260911" if presentation_only else OUT
    report_dir.mkdir(parents=True, exist_ok=True)
    metadata={'kernelspec':{'name':'python3','display_name':'Python 3','language':'python'},
              'language_info':{'name':'python'},'research_status':'exploratory_hypothesis_not_validated',
              'input_sha256':{str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest()
                              for p in [NBDIR/'two_layer_model.py',Path(__file__)]},
              'electrodes':'collinear ideal points: I at +/-L/2, V at +/-L/4; no contact impedance',
              'new_fem_solves':0}
    nb=nbf.v4.new_notebook(cells=cells,metadata=metadata)
    if presentation_only:
        previous_path = NBDIR / (NAME + '.ipynb')
        previous = nbf.read(previous_path, as_version=4)
        old_code = [c for c in previous.cells if c.cell_type == 'code']
        new_code = [c for c in nb.cells if c.cell_type == 'code']
        if [c.source for c in old_code] != [c.source for c in new_code]:
            raise ValueError('Presentation-only export requires unchanged numerical cell sources.')
        core_key = str((NBDIR / 'two_layer_model.py').relative_to(ROOT))
        if previous.metadata['input_sha256'][core_key] != metadata['input_sha256'][core_key]:
            raise ValueError('Analytical core changed since the retained calculation.')
        if any(c.execution_count is None or any(o.output_type == 'error' for o in c.outputs) for c in old_code):
            raise ValueError('Retained calculation is incomplete or contains an error.')
        for new, old in zip(new_code, old_code):
            new.update(old)
        nb.metadata.update(previous.metadata)
        nb.metadata.update(metadata)
        nb.metadata['computation_provenance'] = previous.metadata.get('computation_provenance', {
            'input_sha256': dict(previous.metadata['input_sha256']),
            'source_notebook_sha256': hashlib.sha256(previous_path.read_bytes()).hexdigest()})
        nb.metadata['computation_provenance']['retained_code_outputs_sha256'] = hashlib.sha256(
            json.dumps([(c.source, c.outputs) for c in old_code], ensure_ascii=False, sort_keys=True).encode()).hexdigest()
    else:
        NotebookClient(nb,timeout=180,kernel_name='python3',resources={'metadata':{'path':str(NBDIR)}}).execute()
    nb.metadata['last_build_mode'] = 'presentation_only' if presentation_only else 'execute'
    nbf.validate(nb)
    p=NBDIR/(NAME+'.ipynb');nbf.write(nb,p)
    html,_=HTMLExporter(exclude_input=True,exclude_input_prompt=True,exclude_output_prompt=True).from_notebook_node(nb)
    p.with_suffix('.html').write_text(html,encoding='utf-8')
    soup=BeautifulSoup(html,'html.parser')
    assert not soup.select('.jp-CodeCell .jp-InputArea')
    assert 'def objective(x)' not in html
    for tag in soup(['script','style']):tag.decompose()
    reader=(soup.select_one('main') or soup.body).get_text('\n',strip=True)
    (report_dir/'reader_visible_text.txt').write_text(reader,encoding='utf-8')
    summary={'build_mode': nb.metadata['last_build_mode'], 'executed_cells_this_build': 0 if presentation_only else 3, 'executed_cells':sum(c.cell_type=='code' and c.execution_count is not None for c in nb.cells),
             'tables':len(soup.select('table')),'figures':len(soup.select('img')),'reader_chars':len(reader),
             'versions':{'python':platform.python_version(),'numpy':numpy.__version__,'scipy':scipy.__version__},
             'git_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),
             'working_tree_dirty':bool(subprocess.check_output(['git','status','--porcelain','--untracked-files=no'],cwd=ROOT)),
             'files_sha256':{str(x.relative_to(ROOT)):hashlib.sha256(x.read_bytes()).hexdigest()
                             for x in [p,p.with_suffix('.html'),report_dir/'reader_visible_text.txt']}}
    assert summary['executed_cells']==3 and summary['figures']==3
    (report_dir/'artifact_inventory.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(summary,ensure_ascii=False))


if __name__=='__main__':
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--presentation-only', action='store_true', help='Retain prior numerical code and outputs; revise prose and export HTML.')
    build(presentation_only=parser.parse_args().presentation_only)
